items=[]
for number,(category,question,points,anchors) in enumerate(DATA,1):
    evidence=[]
    for ac,needle,section in anchors:
        filename=f'AC_20-{ac}.pdf'
        matches=[s for s in sources if s['knowledge_base_id']==PDF_KB and s['file_name']==filename and needle.casefold() in s['content'].casefold()]
        assert matches,(number,filename,needle)
        selected=min(matches,key=lambda s:len(s['content']))
        pos=selected['content'].casefold().index(needle.casefold())
        evidence.append({'document':filename,'section':section,'chunk_id':selected['id'],'quote':selected['content'][max(0,pos-50):pos+900]})
    acs={a[0].lower() for a in anchors}
    candidates=[{'id':p['id'],'slug':p['slug'],'title':p['title']} for p in pages if p['knowledge_base_id']==WIKI_KB and any('20-'+ac in (p['content']+' '+p['title']).lower() for ac in acs)]
    items.append({'id':f'FAA-WIKI-{number:02d}','category':category,'question':question,'required_points':points,'evidence':evidence,'wiki_candidate_pages':candidates,'gold_status':'verified_against_ingested_text','limitations':'按已入库原文核对；未逐页复核PDF图像；不判断法规现行有效性。'})

(ROOT/'questions.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in items),encoding='utf-8')
(ROOT/'questions_only.txt').write_text('\n\n'.join(x['id']+' '+x['question'] for x in items),encoding='utf-8')
lines=['# FAA-AC：普通RAG与Wiki对照题集','', '生成日期：2026-10-13。20题：基础5、单文档综合6、跨资料4、信息不足5。','', '依据两个知识库实际入库文本编制，未运行问答测试，不预设Wiki一定获胜。参考答案用于库内检索评测，不作现行法规或具体工程放行意见。','',f'- PDF库：`{PDF_KB}`（9个PDF、210个切片、1个Wiki页面）。',f'- 专题Wiki库：`{WIKI_KB}`（9份来源拆为15个Markdown、763个切片、151个Wiki页面）。','', '直接对比两库只能衡量当前两种配置的总体表现：格式、分卷、切片和Wiki均不同。若要归因于Wiki，应在同一专题库、同一原文切片条件下比较Wiki关闭/开启，并核对实际进入上下文的Wiki内容。PDF库也存在Wiki页，基线必须确认禁用Wiki检索。','', '所有测试使用同一模型、提示词、检索参数、上下文预算；关闭网络搜索、每题新会话。每组建议重复3次。只发送问题及统一提示词，不发送答案和证据。','', '统一提示词：仅根据所选知识库回答。说明适用条件，区分要求、可接受方法和建议；引用文件号及可核验段落。资料不足时说明缺少什么，不补造数值或外部标准内容。','', '逐题评分：每个必答要点记0/1，按已得分/总要点归一化；引用支持性另记0/1；记录编造和错误适用。Wiki胜出须是正确性、要点覆盖或引用有实质改善，措辞差异不算。信息不足题不以回答更长计分。','', '同时保存：原文命中chunk_id、Wiki命中page_id、实际上下文、最终引用、延迟。找不到Wiki输入证据的结果不能称为Wiki贡献。','', '标准答案逐条依据已入库原文；没有人工核对PDF图像页码，故以文件、章节和chunk_id为锚点，不伪造页码。Wiki候选页不作为标准答案来源。','', '优先测试：06、07、08、09、11、12、13、14、15。普通RAG同样答对是有效结果；不可事后只保留Wiki获胜的题。','']
for x in items:
    lines += [f"## {x['id']} · {x['category']}",'',x['question'],'','参考答案必答要点：','']
    lines += ['- '+point for point in x['required_points']]
    lines += ['','原文依据：','']
    lines += [f"- {e['document']}；{e['section']}；chunk `{e['chunk_id']}`。" for e in x['evidence']]
    lines += ['']
(ROOT/'README.md').write_text('\n'.join(lines),encoding='utf-8')
assert len(items)==20 and len({x['id'] for x in items})==20
print('Created 20 grounded questions, answer checklist, and source anchors.')
